class Util {
    static utf8 = {
        /* Uint8Array -> String */
        decode: b => String.fromCharCode.apply(null, b),
        /* String -> Uint8Array */
        encode: s => Uint8Array.from(s.split("").map(x => x.charCodeAt(0)))
    }

    static b64 = {
        /* b64 String -> Uint8Array */
        decode: s => Uint8Array.from(atob(s), c => c.charCodeAt(0)),
        /* Uint8Array -> b64 String */
        encode: b => btoa(String.fromCharCode(...new Uint8Array(b)))
    };

    static sequenceEquals(arr1, arr2) {
        if (arr1.length !== arr2.length)
            return false;
        return Array.from(arr1).every((value, index) => value === arr2[index]);
    }

    static safeStringify(v) {
        if (v === null)
            return "null";
        if (v === undefined)
            return "undefined";
        if (typeof v === "string")
            return v;

        if (v instanceof ArrayBuffer) {
            return `ArrayBuffer(${v.byteLength})`;
        }
        if (ArrayBuffer.isView(v)) {
            const ctorName = v.constructor.name;
            const length = v instanceof DataView ? v.byteLength : v.length;
            return `${ctorName}(${length})`;
        }
        if (Array.isArray(v)) {
            return `[${v.map(Util.safeStringify).join(", ")}]`;
        }

        try {
            return JSON.stringify(v);
        } catch (e) {
            return String(v);
        }
    }

    static proxy(object, method, handler) {
        const original = object[method];
        if (typeof original !== "function")
            return;

        Object.defineProperty(object, method, {
            value: new Proxy(original, { apply: handler }),
            configurable: true,
            writable: true
        });
    };

    static logEme(eventName, args, func) {
        let err;
        try {
            return func();
        } catch(e) {
            err = e;
            throw e;
        } finally {
            Util.emit(eventName, {
                success: !err,
                args: Util.safeStringify(args)
            });
        }
    }

    static emit(type, data, { timeoutMs = 30000 } = {}) {
        return new Promise((resolve, reject) => {
            const requestId = crypto.randomUUID();

            const timer = timeoutMs
                ? setTimeout(() => {
                    document.removeEventListener('__ext_responseReceived', responseHandler);
                    reject(new Error(`Timed out waiting for response to "${type}" (${requestId})`));
                }, timeoutMs)
                : null;

            const responseHandler = (event) => {
                const { detail } = event;
                if (!detail || detail.requestId !== requestId)
                    return;

                document.removeEventListener('__ext_responseReceived', responseHandler);
                if (timer)
                    clearTimeout(timer);

                if (detail.error) {
                    reject(new Error(detail.error));
                } else {
                    resolve(detail.body);
                }
            };
            document.addEventListener('__ext_responseReceived', responseHandler);

            const requestEvent = new CustomEvent('__ext_response', {
                detail: {
                    type,
                    body: data,
                    requestId,
                }
            });
            document.dispatchEvent(requestEvent);
        });
    }

    static getManifestType(text) {
        const lower = text.toLowerCase();
        if (lower.includes('<mpd') && lower.includes('</mpd>')) {
            return "DASH";
        } else if (lower.includes('#extm3u')) {
            if (lower.includes('#ext-x-stream-inf')) {
                return "HLS_MASTER";
            } else {
                return "HLS_PLAYLIST";
            }
        } else if (lower.includes('<smoothstreamingmedia') && lower.includes('</smoothstreamingmedia>')) {
            return "MSS";
        }
    }

    static decodeArrayBuffer(buffer) {
        if (!buffer || buffer.byteLength === 0)
            return null;

        const arr = new Uint8Array(buffer);
        const decoder = new TextDecoder('utf-8', { fatal: false });

        return arr.length <= 4000
            ? decoder.decode(arr)
            : decoder.decode(arr.slice(0, 2000)) + decoder.decode(arr.slice(-2000));
    }

    static async blobToText(blob) {
        if (!blob)
            return null;

        const isTextLike = blob.type.startsWith('text/') || blob.type.includes('xml') || blob.type.includes('json');

        if (!isTextLike && blob.size >= 2_000_000)
            return null;
        if (blob.size <= 4000)
            return blob.text();

        const head = await blob.slice(0, 2000).text();
        const tail = await blob.slice(-2000).text();
        return head + tail;
    }
}
class AES_CMAC {
    BLOCK_SIZE = 16;
    XOR_RIGHT = new Uint8Array([
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x87
    ]);
    EMPTY_BLOCK_SIZE_BUFFER = new Uint8Array(this.BLOCK_SIZE);

    constructor(key) {
        if (![16, 24, 32].includes(key.length)) {
            throw new Error("Key size must be 128, 192, or 256 bits.");
        }
        this._key = key;
    }

    calculate(message) {
        this._subkeys = this._generateSubkeys();
        const blockCount = this._getBlockCount(message);

        let x = this.EMPTY_BLOCK_SIZE_BUFFER;
        let y;

        for (let i = 0; i < blockCount - 1; i++) {
            const from = i * this.BLOCK_SIZE;
            const block = message.subarray(from, from + this.BLOCK_SIZE);
            y = this._xor(x, block);
            x = this._aes(y);
        }

        y = this._xor(x, this._getLastBlock(message));
        x = this._aes(y);

        return x;
    }

    _generateSubkeys() {
        const l = this._aes(this.EMPTY_BLOCK_SIZE_BUFFER);

        let first = this._bitShiftLeft(l);
        if (l[0] & 0x80) {
            first = this._xor(first, this.XOR_RIGHT);
        }

        let second = this._bitShiftLeft(first);
        if (first[0] & 0x80) {
            second = this._xor(second, this.XOR_RIGHT);
        }

        return { first: first, second: second };
    }

    _getBlockCount(message) {
        const blockCount = Math.ceil(message.length / this.BLOCK_SIZE);
        return blockCount === 0 ? 1 : blockCount;
    }

    _aes(message) {
        const keyBuffer = forge.util.createBuffer(this._key, 'raw');
        const cipher = forge.cipher.createCipher('AES-CBC', keyBuffer);

        const iv = forge.util.createBuffer(new Uint8Array(16), 'raw');
        cipher.start({
            iv: iv.getBytes()
        });

        cipher.update(forge.util.createBuffer(message));
        cipher.finish();

        const outputBuffer = cipher.output;
        return new Uint8Array(outputBuffer.getBytes().slice(0, 16).split('').map(c => c.charCodeAt(0)));
    }

    _getLastBlock(message) {
        const blockCount = this._getBlockCount(message);
        const paddedBlock = this._padding(message, blockCount - 1);

        let complete = false;
        if (message.length > 0) {
            complete = message.length % this.BLOCK_SIZE === 0;
        }

        const key = complete ? this._subkeys.first : this._subkeys.second;
        return this._xor(paddedBlock, key);
    }

    _padding(message, blockIndex) {
        const block = new Uint8Array(this.BLOCK_SIZE);

        const from = blockIndex * this.BLOCK_SIZE;
        const slice = message.subarray(from, from + this.BLOCK_SIZE);
        block.set(slice);

        if (slice.length !== this.BLOCK_SIZE) {
            block[slice.length] = 0x80;
        }

        return block;
    }

    _bitShiftLeft(input) {
        const output = new Uint8Array(input.length);
        let overflow = 0;
        for (let i = input.length - 1; i >= 0; i--) {
            output[i] = (input[i] << 1) | overflow;
            overflow = input[i] & 0x80 ? 1 : 0;
        }
        return output;
    }

    _xor(a, b) {
        const length = Math.min(a.length, b.length);
        const output = new Uint8Array(length);
        for (let i = 0; i < length; i++) {
            output[i] = a[i] ^ b[i];
        }
        return output;
    }
}




